                LessonPage(id: "course_283_qu_y_a_t_il_vraiment_dans_un_smartphone_p2", title: "À chaque matériau sa fonction", content: ""),
                LessonPage(id: "course_283_qu_y_a_t_il_vraiment_dans_un_smartphone_p3", title: "Un téléphone qui a fait le tour du monde", content: ""),
