        Course(
            id: "course_284_pourquoi_mars_est_elle_devenue_un_desert",
            title: "Pourquoi Mars est-elle devenue un désert ?",
            description: "Il y a plus de 3 milliards d'années, des rivières creusaient des vallées et des crues balayaient la surface de Mars. Aujourd'hui la planète est froide et sèche, mais son eau n'a pas toute disparu.",
            subject: .sciences,
            subcategory: "La Terre et l'Univers",
            lessons: [
                LessonPage(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_intro", title: "Introduction", content: ""),
                LessonPage(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_p1", title: "Il fallait une atmosphère épaisse", content: ""),
                LessonPage(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_p2", title: "Mars a perdu son atmosphère", content: ""),
                LessonPage(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_p3", title: "L'eau n'est pas toute partie", content: ""),
                LessonPage(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_p4", title: "Sèche, mais pas sans eau", content: ""),
            ],
            quiz: [
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q1", question: "Qu'ont trouvé les rovers à la surface de Mars ?", options: ["Des roches et des minéraux formés en présence d'eau liquide", "Des fossiles de plantes anciennes", "Des lacs d'eau liquide encore en place", "Des volcans toujours en activité"], correctIndex: 0, explanation: "Les rovers ont identifié des roches et des minéraux qui ne se forment qu'en présence d'eau liquide, preuve que Mars a été humide."),
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q2", type: .percentageSlider, question: "La pression atmosphérique actuelle de Mars représente quelle part de celle de la Terre ?", explanation: "L'atmosphère martienne est si ténue que sa pression vaut moins de 1 % de la pression terrestre : l'eau liquide y gèle ou s'évapore.", correctValue: 1, sliderMin: 0, sliderMax: 100, tolerance: 2, unit: "%"),
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q3", question: "Pourquoi l'eau liquide ne reste-t-elle pas stable à la surface de Mars aujourd'hui ?", options: ["La pression atmosphérique est trop faible, l'eau gèle ou se transforme en vapeur", "Le sol est trop chaud et la fait bouillir", "Le vent solaire la souffle directement dans l'espace", "Il n'y a plus la moindre trace d'eau sur la planète"], correctIndex: 0, explanation: "Sous une pression inférieure à 1 % de celle de la Terre, l'eau liquide ne peut pas durer en surface : elle gèle ou s'évapore."),
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q4", type: .trueFalse, question: "Vrai ou faux : la faible gravité de Mars l'aide à retenir les gaz de son atmosphère.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "C'est l'inverse : Mars est petite, sa gravité est plus faible que celle de la Terre, et elle retient donc moins bien ses gaz."),
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q5", question: "À quoi servait le champ magnétique que Mars a perdu ?", options: ["À protéger l'atmosphère des particules chargées venues du Soleil", "À maintenir l'eau à l'état liquide", "À retenir la chaleur à la surface", "À attirer les comètes chargées de glace"], correctIndex: 0, explanation: "Le champ magnétique faisait office de bouclier contre le vent solaire ; sans lui, les particules du Soleil arrachent des gaz à la haute atmosphère."),
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q6", question: "Qu'est-ce que le vent solaire ?", options: ["Un flux de particules chargées qui s'échappe du Soleil", "Un courant d'air chaud dans l'atmosphère de Mars", "La lumière visible émise par le Soleil", "Une tempête de poussière à la surface de Mars"], correctIndex: 0, explanation: "Le vent solaire est un flux continu de particules chargées venues du Soleil ; il frappe la haute atmosphère martienne et en arrache des gaz."),
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q7", question: "Selon une étude de 2021, quelle part de l'eau de Mars pourrait être piégée dans les minéraux de sa croûte ?", options: ["Entre 30 et 99 %", "Moins de 5 %", "Exactement la moitié", "Aucune : toute l'eau s'est échappée"], correctIndex: 0, explanation: "L'étude publiée en 2021 dans Science estime qu'entre 30 et 99 % de l'eau martienne pourrait être enfermée chimiquement dans les roches de la croûte."),
        QuizQuestion(id: "course_284_pourquoi_mars_est_elle_devenue_un_desert_q8", type: .trueFalse, question: "Vrai ou faux : Mars est devenue un désert parce que la totalité de son eau s'est échappée dans l'espace.", options: ["Vrai", "Faux"], correctIndex: 1, explanation: "Mars s'est asséchée parce que son atmosphère ne pouvait plus garder l'eau liquide ; une grande partie de l'eau reste gelée aux pôles, enfouie sous le sol ou enfermée dans les roches.")
    ]
