                LessonPage(id: "course_285_pourquoi_la_lune_s_eloigne_t_elle_de_la_p2", title: "La Terre pousse la Lune", content: ""),
                LessonPage(id: "course_285_pourquoi_la_lune_s_eloigne_t_elle_de_la_p3", title: "La Terre ralentit aussi", content: ""),
